  stk asegs m lo (bv_unsigned sp) -> lo + 176 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp mod 16 = 0 -> mem_inv asegs m ->
  (forall (m1 : mem) (spa : Z) (j64 : list byte) (gap : list cell),
     munch [(lo, bv_unsigned sp)]%Z m m1 -> wmono asegs m m1 -> mem_inv asegs m1 ->
     (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176) -> spa mod 32 = 0 ->
     stk asegs m1 lo spa ->
     rw_cells asegs m1 spa [CB 64 j64] ->
     rw_cells asegs m1 (spa + 64) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 64) ->
     rw_cells asegs m1 (bv_unsigned sp + -96) (put_saves s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
     evt asegs Q (MS (mkR ra (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                     F (Z_to_bv 64 P_A_PUT_B) fc None m1 (seg_rom asegs))) ->
  evt asegs Q (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                 F (Z_to_bv 64 P_A_READER_PUT) fc None m (seg_rom asegs)).
